def axis(kind, value=None, source=None, locator=None, status=None):
    return dict(kind=kind, value=value, source=source, locator=locator, status=status)


def record(record_id, entity, claim, source_ids, **axes):
    base = {"id": record_id, "entity": entity, "claim": claim, "source_ids": source_ids,
            "date_axes": {k: axis("not_applicable") for k in
                          ("archaeological_or_physical", "composition", "collection_or_redaction", "extant_witness", "narrated_time")}}
    base["date_axes"].update(axes)
    return base


def main():
    paths = [HERE / "sources.json", HERE / "chronology.json"]
    if any(p.exists() for p in paths):
        raise FileExistsError("Preserve existing chronology/source ledger")
    captures = []
    for p in sorted(RAW.glob("capture-v*.json")):
        captures.extend(json.loads(p.read_text(encoding="utf-8"))["sources"])
    by_id = {r["source_id"]: r for r in captures}
    for source in SOURCES:
        source["accessed_utc_date"] = "2026-10-11"
        source["prior_review_status"] = "New source-scoped reading for this independent review; no claim to be the first use anywhere in the repository."
        source["captures"] = [by_id[w] for w in source["witnesses"] if w in by_id]
    sources = {"scope": "Independent bounded chronology/control audit; download is distinct from inspected scope",
               "sources": SOURCES, "failed_or_limited_routes": [r for r in captures if r.get("error") or "bot" in str(r.get("html_title", "")).lower()]}
    data = [
        record("CH01", "Harappa urban and later occupations", "Kenoyer's site/phase scheme distinguishes2600–1900 BCE urban occupation and1900–1300 BCE Late Harappan occupation.", ["KEN2006"], archaeological_or_physical=axis("author_phase_scheme", {"urban_bce": [2600, 1900], "late_harappan_bce": [1900, 1300]}, "KEN2006", "printed pp. 10–13; Tables 1–2", "site/phase assessment; not a universal single collapse date")),
        record("CH02", "Harappan landscape and posturban settlement", "Physical-channel and settlement observations occupy their own chronological axis.", ["GIO2012"], archaeological_or_physical=axis("physical_process_and_author_phase_context", {"mature_phase_approximate_y_ago": [4500, 3900]}, "GIO2012", "Introduction; Results and Discussion", "retain source's y-ago unit; no calendar bound propagated to a hymn")),
        record("CH03", "Surviving Rigvedic hymns", "The translators offer an approximate composition estimate, while separating inherited poetic conventions.", ["JB2014"], composition=axis("author_estimate", {"approximate_bce": [1400, 1000], "alternative_expression": "second half of the second millennium BCE"}, "JB2014", "Introduction, printed p.5", "contentious philological/material estimate; not inferred from sophistication")),
        record("CH04", "Rigvedic relative layers", "Family Books II–VII form an older core; book X contains major later additions. A book number is not a uniform date for every verse.", ["JB2014"], composition=axis("relative_stratigraphy", "older family-book core, later additions including book X", "JB2014", "Introduction, printed pp. 10,13–15", "no within-book absolute calendar assignment")),
        record("CH05", "Rigvedic collection and recensional fixation", "Collection, later recensions and phonetic/redaction changes are distinct processes.", ["JB2014"], collection_or_redaction=axis("attributed_historical_reconstruction", "Bharata/Kuru sponsorship and subsequent school recensions", "JB2014", "Introduction, printed pp. 14–17", "Kuru claim explicitly attributed to Witzel; archaeological sponsor not independently joined")),
        record("CH06", "Rigvedic manuscript witnesses", "The 2014 introduction describes14th-century and 1464 manuscript witnesses.", ["JB2014"], extant_witness=axis("author_report_of_manuscripts", ["fourteenth-century manuscript at Sampurnanand Sanskrit University", "1464 Bhandarkar Oriental Research Institute manuscript"], "JB2014", "Introduction, printed p.18", "not a current universal oldest-manuscript census")),
        record("CH07", "SB 11.5.1 and RV 10.95", "Later prose embeds older dialogue; its explanatory accuracy remains a separate philological question.", ["JB2014", "RV1095", "SB11"], composition=axis("relative_text_relationship", "later Brahmana explanatory frame for Rigvedic dialogue", "JB2014", "Introduction, printed p.18; SB 11.5.1.1–17", "no absolute composition interval assigned"), narrated_time=axis("literary_sequence", "Pururavas–Urvasi separation and fire-production story", "SB11", "11.5.1.1–17", "no independently dated narrated event")),
        record("CH08", "Early Buddhist discourse collections", "Mnemonic fixed wording and sanctioned revision can coexist across related versions.", ["ALL2022"], composition=axis("relative_textual_formation", "early composition followed by community-specific additions/revisions", "ALL2022", "Introduction; narrative changes; Pratimoksa discussion", "no calendar date assigned to every passage"), narrated_time=axis("mixed_historical_and_literary_representation", "depicted teachings, patrons and events", "ALL2022", "Stylistic Features discussion", "narrative setting alone is not a composition or event date")),
        record("CH09", "LOC Gandhara scroll", "The holding institution dates this physical scroll roughly first century BCE–first century CE.", ["LOC-GAN"], extant_witness=axis("holding_institution_estimate", {"century_range": "first century BCE to first century CE"}, "LOC-GAN", "object-description paragraph", "manuscript bound applies to this object; dating measurements not independently inspected")),
        record("CH10", "Known Gandhari manuscripts in LMU project", "The edition project states a first century BCE–fourth century CE manuscript range.", ["LMU-GAN"], extant_witness=axis("institutional_project_scope", "first century BCE to fourth century CE", "LMU-GAN", "project overview", "different population from the single LOC scroll")),
        record("CH11", "Jain canon and redacting councils", "Wiles separates council traditions from the much later sources used to date them.", ["WIL2006"], collection_or_redaction=axis("tradition_with_disputed_calendar_conversion", "980/993 years after Mahavira and other traditional council accounts", "WIL2006", "printed pp. 61–68,74–76", "neither exact calendar year nor full-canon composition date adopted"), extant_witness=axis("author_manuscript_report", "oldest Svetambara canonical manuscripts, eleventh–twelfth centuries CE", "WIL2006", "printed p.61", "claim retains author's 2006 scope; individual manuscript records not checked")),
        record("CH12", "Avestan corpus", "Ancient linguistic material, later compilation and medieval handwritten witnesses are separated.", ["KEL1987"], composition=axis("relative_linguistic_strata", "Old and Young Avestan material", "KEL1987", "formation/transmission discussion", "no disputed absolute Old Avestan date selected"), collection_or_redaction=axis("author_reconstruction", "Sasanian compilation/writing", "KEL1987", "formation/transmission discussion", "do not date ancient composition by the compilation hypothesis"), extant_witness=axis("medieval_manuscript_families", "medieval manuscripts; article reports 1323 J2/K5 and an older K7a assessment", "KEL1987", "manuscript families", "not adopted as an updated oldest-date census")),
        record("CH13", "Indo-Iranian comparison", "Related ritual/poetic elements supply alternatives to a uniquely Harappan origin.", ["JB2014", "BOY2003", "GNO2004"], composition=axis("comparative_inheritance", "related Indo-Iranian verbal/ritual elements", "JB2014", "Introduction, printed pp.5,10,14", "parallel elements do not reconstruct a single complete institution or exclude later local contribution")),
        record("CH14", "Calcutta-Bairat inscription", "The ruler addresses Buddhist audiences and recommends teachings; this is a written institutional representation.", ["HUL1925"], archaeological_or_physical=axis("royal_inscription_attribution", "Asokan inscription; no exact regnal/calendar date selected in this reviewer ledger", "HUL1925", "introduction attribution; printed pp. 172–174", "actual text inspected via OCR/transcription; facsimile not read"), narrated_time=axis("inscriptional_attribution", "teachings attributed to the Buddha", "HUL1925", "printed pp. 173–174", "cannot date the content of every extant discourse by matching a title")),
    ]
    result = {"status": "reviewer's source-grounded chronology/control ledger; no fitted historical chronology",
              "rules": ["The survival of a complex institution in literature does not date its origin.",
                        "A dated physical copy bounds the existence of that copy's content, not the narrated event's calendar time.",
                        "Relative textual strata can be recorded without converting them into exact years.",
                        "Related traditions, genre selection, later development and selective transmission can coexist.",
                        "A material-to-text continuity route needs independently dated intermediate observations."],
              "records": data}
    paths[0].write_text(json.dumps(sources, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    paths[1].write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps({"source_records": len(SOURCES), "chronology_records": len(data), "witness_attempts": len(captures)}))


if __name__ == "__main__":
    main()
